#!/usr/bin/env node

// Validate the markup generated by the platform.
//
// Check one page of each type, not the whole site. The platform is responsible
// for templates, not content: every article uses doc.njk, so the thousandth
// article will not reveal anything the first one did not. Errors in author
// markup, such as demo HTML, belong to the content repository.
//
// Previously, the unquoted `./dist/**/*.html` glob was expanded by sh, which
// does not support globstar. `**` collapsed to `*`, so the validator checked
// only 27 of 3,495 pages: section indexes and no articles. The article
// templates were not checked at all.

'use strict'

const path = require('path')
const { existsSync } = require('fs')
const { vnu } = require('vnu-jar')

const DIST = 'dist'

// One representative for each page type. Add new page types here so they are checked.
const PAGES = [
  ['index.html', 'home page'],
  ['cpp/index.html', 'section index'],
  ['all/index.html', 'all articles list'],
  ['people/index.html', 'contributors list'],
  ['people/harikumarstudio/index.html', 'contributor page'],
  ['search/index.html', 'search page'],
  ['about/index.html', 'information page'],
  ['subscribe/index.html', 'subscription page'],
  ['offline/index.html', 'offline page'],
  ['404/index.html', 'error page'],
  ['cpp/cs50-algorithms/index.html', 'article with all transforms'],
  ['cpp/index.sc.html', 'section social card'],
  ['cpp/cs50-algorithms/index.sc.html', 'article social card'],
  ['all/index.sc.html', 'all articles social card'],
]

function main() {
  const missing = PAGES.filter(([file]) => !existsSync(path.join(DIST, file)))

  if (missing.length > 0) {
    // A missing page is a failure: either the build stopped generating it or
    // the page type was renamed and this list needs updating.
    console.error('Pages to validate were not found:')
    for (const [file, kind] of missing) {
      console.error(`  ${file} — ${kind}`)
    }
    process.exitCode = 1
    return
  }

  const files = PAGES.map(([file]) => path.join(DIST, file))

  console.log(`Validating ${files.length} pages — one of each type.`)

  vnu
    .check(['--format', 'gnu', '--exit-zero-always', ...files])
    .then((output) => {
      const lines = output.split('\n').filter((line) => line.trim() !== '')
      // Validator warnings are markup suggestions, such as a section missing
      // a heading. Show them, but do not fail the check: social card pages
      // exist only to generate screenshots and do not need headings.
      const errors = lines.filter((line) => /: error/.test(line))
      const warnings = lines.filter((line) => !/: error/.test(line))

      for (const line of warnings) {
        console.log(line)
      }

      if (errors.length === 0) {
        console.log(`\nNo errors. Warnings: ${warnings.length}.`)
        return
      }

      console.error('')
      for (const line of errors) {
        console.error(line)
      }
      console.error(`\nErrors: ${errors.length}.`)
      process.exitCode = 1
    })
    .catch((error) => {
      const message = error.message.trim()

      if (message.includes('UnsupportedClassVersionError')) {
        // vnu-jar accepts any Java version from 11 onward, although the jar is
        // built for 17. On a machine with Java 11–16, it uses the system
        // version and fails with an unclear class-version error.
        console.error('The validator requires Java 17 or newer, but an older version was found in PATH.')
        console.error('Install Java 17+ or remove the older version from PATH so vnu-jar can download its own.')
      } else {
        console.error(message)
      }

      process.exitCode = 1
    })
}

main()
